"""Pinned BWAPI4.4.0 Queen/Nest/Ensnare/Gamete and OpenBW status facts."""
import re,json,hashlib,sys
from pathlib import Path
root=Path(sys.argv[1] if len(sys.argv)>1 else 'work/sources');u=(root/'unit.cpp').read_text();t=(root/'tech.cpp').read_text();w=(root/'weapon.cpp').read_text();up=(root/'upgrade.cpp').read_text();e=(root/'bwgame.h').read_text()
def body(s,n):return re.search(re.escape(n)+r'\[[^\]]+\]\s*=\s*\{(.*?)\};',re.sub(r'//[^\n]*','',s),re.S)[1]
def nums(s,n):return [float(x)for x in re.findall(r'-?\d+(?:\.\d+)?',body(s,n))]
def words(s,n):return re.findall(r'\b[A-Za-z_][A-Za-z_0-9]*\b',body(s,n))
def names(s):return re.findall(r'"([^"]*)"',body(s,'typeNames'))
un=names(u);tn=names(t);wn=names(w);ups=names(up);dims=[[int(x)for x in re.findall(r'\d+',v)]for v in re.findall(r'\{([^{}]+)\}',body(u,'unitDimensions'))];flags=body(u,'unitFlags').split(',');units=[];profiles=[];traits=[]
for name in ['Zerg_Queen','Zerg_Queens_Nest']:
 i=un.index(name);values={k:nums(u,k)[i]for k in ['defaultOreCost','defaultGasCost','defaultTimeCost','defaultMaxHP','defaultMaxSP','defaultArmorAmount','unitSupplyProvided','unitSupplyRequired','unitTopSpeeds','sightRangeTiles']};values={k:int(v)if v.is_integer()else v for k,v in values.items()};units.append({'name':name,'bwapiId':i,**values,'dimensions':dims[i]});profiles.append({'name':name,'size':words(u,'unitSize')[i].lower(),'bounds':dims[i][2:],'groundWeapon':words(u,'groundWeapon')[i],'airWeapon':words(u,'airWeapon')[i],'hits':int(nums(u,'groundWeaponHits')[i])});traits.append({'name':name,'spaceRequired':int(nums(u,'unitSpaceRequired')[i]),'spaceProvided':int(nums(u,'unitSpaceProvided')[i]),'flyer':'Flyer'in flags[i],'detector':False,'permanentCloak':False})
i=tn.index('Ensnare');j=wn.index('Ensnare');technology={'name':'Ensnare','id':'ensnare','title':'인스네어','producer':words(t,'whatResearches')[i].lower().replace('_','-'),'minerals':int(nums(t,'defaultOreCost')[i]),'gas':int(nums(t,'defaultOreCost')[i]),'frames':int(nums(t,'defaultTimeCost')[i]),'energy':int(nums(t,'defaultEnergyCost')[i]),'rangePixels':int(nums(w,'wpnMaxRange')[j])};k=ups.index('Gamete_Meiosis');upgrade={'name':'Gamete_Meiosis','id':'gamete-meiosis','unitId':'zerg-queen','title':'게메이트 마이오시스','producer':words(up,'whatUpgrades')[k].lower().replace('_','-'),'minerals':int(nums(up,'defaultOreCostBase')[k]),'gas':int(nums(up,'defaultOreCostBase')[k]),'frames':int(nums(up,'defaultTimeCostBase')[k]),'maxLevel':int(nums(up,'defaultMaxRepeats')[k])}
area=e[e.index('void ensnare_unit'):e.index('void consume_unit')];assert 'u->ensnare_timer = 75' in area and 'square_at(pos, 64)' in area and 'u_burrowed(target)'in area;assert 'if (u->ensnare_timer) remove_ensnare(u)'in e[e.index('void restore_unit'):e.index('void emp_shockwave')];assert 'if (mod < 0) speed /= 2u' in e and 'if (mod < 0) cooldown += cooldown / 4' in e
out={'source':{'bwapiTag':'v4.4.0','openbwCommit':json.loads((root/'openbw-commit.json').read_text())['sha'],'sha256':{n:hashlib.sha256((root/n).read_bytes()).hexdigest()for n in ['unit.cpp','tech.cpp','weapon.cpp','upgrade.cpp','bwgame.h']}},'units':units,'profiles':profiles,'traits':traits,'technology':technology,'upgrade':upgrade,'ensnare':{'statusCycles':75,'framesPerCycle':8,'halfWidthPixels':64,'speedDivisor':2,'cooldownExtraDivisor':4,'revealsCloak':True,'restorable':True}}
Path('app/stark-rift/data/queen-original.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n');print(json.dumps(out,ensure_ascii=False))
